#include <stdio.h>
#include <stdlib.h>

static int compare_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) return 0;

    long long *A = malloc((size_t)N * sizeof(long long));
    long long total = 0;

    for (int i = 0; i < N; ++i) {
        scanf("%lld", &A[i]);
        total += A[i];
    }

    if (K * C == N) {
        printf("0\n");
        free(A);
        return 0;
    }

    if (C == 1) {
        qsort(A, (size_t)N, sizeof(long long), compare_ll);
        long long covered = 0;
        for (int i = 0; i < K; ++i) covered += A[i];
        printf("%lld\n", total - covered);
        free(A);
        return 0;
    }

    long long *prefix = malloc((size_t)(N + 1) * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < N; ++i) prefix[i + 1] = prefix[i] + A[i];

    const long long INF = LLONG_MAX / 4;
    long long *prev = calloc((size_t)(N + 1), sizeof(long long));
    long long *cur = malloc((size_t)(N + 1) * sizeof(long long));

    for (int j = 1; j <= K; ++j) {
        int start = j * C;
        cur[start - 1] = INF;

        for (int i = start; i <= N; ++i) {
            long long best = cur[i - 1];
            long long candidate = prev[i - C] + prefix[i] - prefix[i - C];
            if (candidate < best) best = candidate;
            cur[i] = best;
        }

        long long *tmp = prev;
        prev = cur;
        cur = tmp;
    }

    printf("%lld\n", total - prev[N]);

    free(A);
    free(prefix);
    free(prev);
    free(cur);
    return 0;
}
