#include <string.h>
#include <limits.h>

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) return 0;

    int *A = malloc((size_t)N * sizeof(int));
    long long total = 0;
    for (int i = 0; i < N; ++i) {
        scanf("%d", &A[i]);
        total += A[i];
    }

    if (C == 1) {
        qsort(A, N, sizeof(int), compare_ints);
        long long covered = 0;
        for (int i = 0; i < K; ++i) covered += A[i];
        printf("%lld\n", total - covered);
        free(A);
        return 0;
    }

    long long *prefix = malloc((size_t)(N + 1) * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < N; ++i) prefix[i + 1] = prefix[i] + A[i];

    int width = K + 1;
    int rows = C + 1;
    long long *dp = malloc((size_t)rows * width * sizeof(long long));
    const long long INF = LLONG_MAX / 4;

    for (size_t i = 0; i < (size_t)rows * width; ++i) dp[i] = INF;
    dp[0] = 0;

    for (int i = 1; i <= N; ++i) {
        int dest_row = i % rows;
        int prev_row = (i - 1) % rows;
        long long *dest = dp + (size_t)dest_row * width;
        long long *prev = dp + (size_t)prev_row * width;

        memcpy(dest, prev, (size_t)width * sizeof(long long));

        if (i >= C) {
            int source_row = (i - C) % rows;
            long long *source = dp + (size_t)source_row * width;
            long long segment_sum = prefix[i] - prefix[i - C];
            int max_count = i / C;
            if (max_count > K) max_count = K;

            for (int count = 1; count <= max_count; ++count) {
                long long base = source[count - 1];
                if (base != INF) {
                    long long candidate = base + segment_sum;
                    if (candidate < dest[count]) dest[count] = candidate;
                }
            }
        }
    }

    long long minimum_covered = dp[(size_t)(N % rows) * width + K];
    printf("%lld\n", total - minimum_covered);

    free(dp);
    free(prefix);
    free(A);
    return 0;
}
